@_default_transform.register(ZeroSumNormalRV)
def zerosum_default_transform(op, rv):
    n_zerosum_axes = tuple(np.arange(-op.ndim_supp, 0))
    return ZeroSumTransform(n_zerosum_axes)


@_logprob.register(ZeroSumNormalRV)
def zerosumnormal_logp(op, values, normal_dist, sigma, support_shape, **kwargs):
    (value,) = values
    shape = value.shape
    n_zerosum_axes = op.ndim_supp

    _deg_free_support_shape = shape[-n_zerosum_axes:] - 1
    _degrees_of_freedom = pt.prod(_deg_free_support_shape)

    zerosums = [
        pt.all(pt.isclose(pt.mean(value, axis=-axis - 1), 0, atol=1e-9))
        for axis in range(n_zerosum_axes)
    ]

    # The value is a projection of an unconstrained standard Normal onto the
    # zero-sum subspace.  The projection used by ``ZeroSumTransform`` is
    # orthonormal, so the log-density is simply the reduced-coordinate Normal
    # density evaluated at the constrained value:
    #
    #     log p(x) = -df/2 * log(2 * pi * sigma**2) - ||x||^2 / (2 * sigma**2)
    #
    # where ``df`` is the number of free coordinates of the constrained
    # support.  Summing only over the constrained trailing axes keeps any
    # leading batch dimensions intact.
    out = -0.5 * _degrees_of_freedom * pt.log(2 * np.pi * sigma**2) - 0.5 * pt.sum(
        pt.square(value), axis=tuple(np.arange(-n_zerosum_axes, 0))
    ) / sigma**2

    return check_parameters(out, *zerosums, msg="mean(value, axis=n_zerosum_axes) = 0")
